func eq(t *testing.T, got []any, want []any) {
	t.Helper()
	if got == nil {
		t.Fatalf("got nil, want %v", want)
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got %v, want %v", got, want)
	}
}

func mustErr(t *testing.T, path string) {
	t.Helper()
	got, err := Query(doc(t, `{}`), path)
	if err == nil {
		t.Fatalf("path %q: expected error, got %v", path, got)
	}
	if got != nil {
		t.Fatalf("path %q: expected nil result, got %v", path, got)
	}
}

func TestSpec(t *testing.T) {
	d := doc(t, `{"a":{"b":[{"c":1},{"c":2}],"x":[10,20,30]},"list":[{"y":1},{"y":2}]}`)

