	eq(t, mustQuery(t, d, "$.x"), []any{[]any{10.0, 20.0, 30.0}})
	eq(t, mustQuery(t, d, "$.a.b[1].c"), []any{2.0})
	eq(t, mustQuery(t, d, "$.a.b[-1].c"), []any{2.0})
	eq(t, mustQuery(t, d, "$.a.b[5].c"), []any{})            // out of range: no error
	eq(t, mustQuery(t, d, "$.a.b[-99].c"), []any{})           // negative out of range
	eq(t, mustQuery(t, d, "$.a.missing"), []any{})            // missing key
	eq(t, mustQuery(t, d, "$.x.a"), []any{})                  // member on non-object
	eq(t, mustQuery(t, d, "$.a[0]"), []any{})                 // index on non-array
	eq(t, mustQuery(t, d, `$.a.b["c"]`), []any{1.0, 2.0})
	eq(t, mustQuery(t, d, `$.a.b[*].c`), []any{1.0, 2.0})
	eq(t, mustQuery(t, d, `$.a.b[*]["c"]`), []any{1.0, 2.0})
	eq(t, mustQuery(t, d, "$.a.b[*]"), []any{map[string]any{"c": 1.0}, map[string]any{"c": 2.0}})
	eq(t, mustQuery(t, d, "$.*"), []any{
		[]any{map[string]any{"y": 1.0}, map[string]any{"y": 2.0}},
		map[string]any{"b": []any{map[string]any{"c": 1.0}, map[string]any{"c": 2.0}}, "x": []any{10.0, 20.0, 30.0}},
	}) // object values in key ascending: a, list
	eq(t, mustQuery(t, d, "$.list[*].y"), []any{1.0, 2.0})
	eq(t, mustQuery(t, d, "$.list.y"), []any{})               // member on array
	eq(t, mustQuery(t, d, "$.a.b[2]"), []any{})              // 2 out of range
	eq(t, mustQuery(t, d, "$.list..y"), []any{1.0, 2.0})
	eq(t, mustQuery(t, d, "$.a..c"), []any{1.0, 2.0})
	eq(t, mustQuery(t, d, "$.missing..c"), []any{})
	eq(t, mustQuery(t, d, `$.a.b[2]["c"]`), []any{})

	// pre-order with the node's own match first
	d2 := doc(t, `{"c":9,"k":{"c":1}}`)
	eq(t, mustQuery(t, d2, "$..c"), []any{9.0, 1.0})
	// children in key order
	d3 := doc(t, `{"z":{"c":2},"a":{"c":1}}`)
	eq(t, mustQuery(t, d3, "$..c"), []any{1.0, 2.0})
	// recursive descent on array element containing an object
	d4 := doc(t, `[{"c":1},{"c":2}]`)
	eq(t, mustQuery(t, d4, "$..c"), []any{1.0, 2.0})
	// nil values are fine
	d5 := doc(t, `{"a":null}`)
	got, err := Query(d5, "$.a")
	if err != nil || !reflect.DeepEqual(got, []any{nil}) {
		t.Fatalf("null: %v %v", got, err)
	}

