	// negative index on array of 2: [-1] is last
	eq(t, mustQuery(t, d6, `$.["a\"b\\c"]`), []any{7.0})
	eq(t, mustQuery(t, d, "$.x[-1]"), []any{30.0})
	eq(t, mustQuery(t, d, "$.x[-3]"), []any{10.0})
}

